export const exact = (a,b) => Array.isArray(a)&&a.length===b.length&&new Set(a).size===a.length&&a.every(v=>b.includes(v));
export const concurrency=(rps,ms)=>Math.ceil(Math.max(0,rps)*Math.max(0,ms)/1000);
export const shards=(mb,records,out)=>Math.ceil(Math.max(mb,records/1000,out/2));
export const usable=(prefix)=>2**(32-prefix)-5;
export function iam(v){if(v.deny)return {allow:false,reason:'An applicable explicit deny wins. Deny yang berlaku mengalahkan Allow.'};if(!v.identity)return {allow:false,reason:'No identity-based allow. Default is implicit deny — izin belum diberikan.'};if(!v.boundary)return {allow:false,reason:'The permissions boundary does not allow this action. Batas identity membatasi grant.'};if(!v.scp)return {allow:false,reason:'The applicable SCP path does not allow this action. Pagar organisasi memblokir.'};return {allow:true,reason:'Identity allows it, both ceilings permit it, and no explicit deny applies. Semua gate pada model ini lolos.'};}
export function network(v){if(v.route==='none')return {ok:false,reason:'No destination route. Paket berhenti di route table.'};if(v.route==='igw')return {ok:false,reason:'An IPv4 IGW route alone cannot provide internet access to this EC2 instance: it has no public IPv4 address. Gunakan NAT untuk private IPv4 egress.'};if(v.route==='endpoint'&&v.target==='internet')return {ok:false,reason:'An S3 gateway endpoint routes S3 traffic only. Endpoint bukan jalan keluar ke arbitrary public APIs.'};if(!v.sg)return {ok:false,reason:'The security group blocks the initiated outbound flow. Tambahkan scoped egress rule.'};if(!v.nacl)return {ok:false,reason:'The stateless NACL blocks outbound traffic or the return ephemeral ports. Periksa dua arah.'};if(v.target==='s3'&&!v.policy)return {ok:false,reason:'The network path works but authorization fails. Periksa IAM, bucket, endpoint and KMS policies as applicable.'};return {ok:true,reason:v.route==='endpoint'?'S3 traffic follows the S3 prefix-list route to the gateway endpoint. Tidak perlu NAT atau public IPv4.':'Traffic uses the NAT gateway and its public-subnet IGW route. Return packets follow the established translation.'};}
export const cache=(rps,hit,origin,fast)=>({origin:rps*(1-hit/100),latency:origin*(1-hit/100)+fast*hit/100});
export const recovery=(detect,provision,restore,validate)=>detect+provision+restore+validate;
export function scoreQuiz(session,questions){const list=session.ids.map(id=>questions.find(q=>q.id===id)).filter(Boolean);const correct=list.filter(q=>exact(session.answers[q.id]||[],q.correct)).length;return {total:list.length,correct,percent:list.length?Math.round(correct/list.length*100):0,domains:[1,2,3,4].map(id=>({id,total:list.filter(q=>q.domain===id).length,correct:list.filter(q=>q.domain===id&&exact(session.answers[q.id]||[],q.correct)).length}))};}
